// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListFlows The kinds that have a flow (a stepped definition, contract/flows). A kind without one is a sheet: one step, every field.
	// (GET /flows)
	ListFlows(w http.ResponseWriter, r *http.Request)
	// GetFlow The flow document for a kind, as written in the contract
	// (GET /flows/{kind})
	GetFlow(w http.ResponseWriter, r *http.Request, kind KindParam)
	// GetGoalTree The goal tree, computed from every Goal manifest and the reference index
	// (GET /goals/tree)
	GetGoalTree(w http.ResponseWriter, r *http.Request)
	// GetHealth Liveness check
	// (GET /health)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// ListKinds Every registered kind and how many manifests exist for it
	// (GET /kinds)
	ListKinds(w http.ResponseWriter, r *http.Request)
	// GetGapChecks Whether a gap can be used for what a gap register is for. Advisory only, like a programme's: every one of these reads a manifest other than the gap.
	// (GET /manifests/Gap/{id}/checks)
	GetGapChecks(w http.ResponseWriter, r *http.Request, id IdParam)
	// GetGapCoverage Which part of a gap each piece of work addresses, and which parts nobody does. Derived from the citations, never stored: work declares what it reaches and this reads it back, the same way a programme's members are derived. Addressed, not closed: whether the shortfall narrowed is what the gap's measure reads.
	// (GET /manifests/Gap/{id}/coverage)
	GetGapCoverage(w http.ResponseWriter, r *http.Request, id IdParam)
	// DeleteGoal Delete a goal (goals are easily mutable). Allowed only when nothing currently references it; every committed version of every manifest remains in the immutable manifest store regardless (a tombstone, not a destructive delete), so this never disturbs history or audit -- it only stops the goal from being listed, picked or resolved as a reference going forward.
	// (DELETE /manifests/Goal/{id})
	DeleteGoal(w http.ResponseWriter, r *http.Request, id IdParam)
	// GetGoalChecks Whether a goal can be assessed. Checks never block a save.
	// (GET /manifests/Goal/{id}/checks)
	GetGoalChecks(w http.ResponseWriter, r *http.Request, id IdParam)
	// GetOperationCharterHtml Operation charter rendered as HTML from the working copy: what the service does and when, who runs it, what it is part of, how it is measured, what it uses and produces, and which projects will hand over to it. Derived, like every other view.
	// (GET /manifests/Operation/{id}/charter.html)
	GetOperationCharterHtml(w http.ResponseWriter, r *http.Request, id IdParam)
	// GetOperationChecks Whether an operation is described well enough to be run and measured, step by step. Advisory only.
	// (GET /manifests/Operation/{id}/checks)
	GetOperationChecks(w http.ResponseWriter, r *http.Request, id IdParam)
	// GetProgrammeCharterHtml Programme charter rendered as HTML from the working copy: what it is for, what is wrong, what it serves, how it believes the change happens, what is inside it and who runs it. Derived, like every other view, so there is nothing to keep in step.
	// (GET /manifests/Programme/{id}/charter.html)
	GetProgrammeCharterHtml(w http.ResponseWriter, r *http.Request, id IdParam)
	// GetProgrammeChecks Whether a programme can be judged on what a programme is judged on. Advisory only: none of these has a state that stops anything, because most of them can change when somebody edits a different manifest.
	// (GET /manifests/Programme/{id}/checks)
	GetProgrammeChecks(w http.ResponseWriter, r *http.Request, id IdParam)
	// GetProjectCharterHtml Project charter rendered as HTML from the latest snapshot (or working copy with ?working=true).
	// (GET /manifests/Project/{id}/charter.html)
	GetProjectCharterHtml(w http.ResponseWriter, r *http.Request, id IdParam, params GetProjectCharterHtmlParams)
	// GetProjectChecks Every per-section check for a project (goals, aim, scope, deliverables, beneficiaries, timeline, data, risks, closing, landing). Checks never block a save; state block stops submission.
	// (GET /manifests/Project/{id}/checks)
	GetProjectChecks(w http.ResponseWriter, r *http.Request, id IdParam)
	// GetProjectState A project's current state and its full transition history
	// (GET /manifests/Project/{id}/state)
	GetProjectState(w http.ResponseWriter, r *http.Request, id IdParam)
	// TransitionProjectState Move a project to a new state. draft to in review is refused with 422 (the blocking checks as problems) unless every blocking check currently passes; cancelled requires a reason; every other move must be the next state in the fixed sequence.
	// (POST /manifests/Project/{id}/state)
	TransitionProjectState(w http.ResponseWriter, r *http.Request, id IdParam)
	// ListManifests Summaries of every manifest of a kind
	// (GET /manifests/{kind})
	ListManifests(w http.ResponseWriter, r *http.Request, kind KindParam, params ListManifestsParams)
	// DeleteManifest Exclude a manifest from the live state (a tombstone operation). Allowed only when nothing currently references it; the file remains on disk, and the exclusion can be recovered. Applies the leaf rule: a manifest is a leaf if no live manifest references it.
	// (DELETE /manifests/{kind}/{id})
	DeleteManifest(w http.ResponseWriter, r *http.Request, kind KindParam, id IdParam)
	// GetManifest The current version of one manifest
	// (GET /manifests/{kind}/{id})
	GetManifest(w http.ResponseWriter, r *http.Request, kind KindParam, id IdParam)
	// PutManifest Validate and commit a new version of a manifest: the save that promotes a staged draft into the vault's own tree and its include list, in one atomic journalled write, then clears the draft. Only this ref's draft; other drafts are left alone, because there may be many and saving one is not a decision about the rest.
	// (PUT /manifests/{kind}/{id})
	PutManifest(w http.ResponseWriter, r *http.Request, kind KindParam, id IdParam)
	// GetCharterPdf The charter of a project, programme or operation as a PDF, printed from the same HTML the charter page shows. Needs a chromium: the vault's spec.chromium, the CHROMIUM environment variable, or one on the PATH.
	// (GET /manifests/{kind}/{id}/charter.pdf)
	GetCharterPdf(w http.ResponseWriter, r *http.Request, kind KindParam, id IdParam, params GetCharterPdfParams)
	// DiffManifest Structural diff between two versions
	// (GET /manifests/{kind}/{id}/diff)
	DiffManifest(w http.ResponseWriter, r *http.Request, kind KindParam, id IdParam, params DiffManifestParams)
	// GetSharedDocument The shared draft of a manifest, as an Automerge document id
	// (GET /manifests/{kind}/{id}/document)
	GetSharedDocument(w http.ResponseWriter, r *http.Request, kind KindParam, id IdParam)
	// GetReferences What a manifest points to, and what points back at it
	// (GET /manifests/{kind}/{id}/references)
	GetReferences(w http.ResponseWriter, r *http.Request, kind KindParam, id IdParam)
	// PostSnapshot Create an explicit snapshot (version) with a reason
	// (POST /manifests/{kind}/{id}/snapshots)
	PostSnapshot(w http.ResponseWriter, r *http.Request, kind KindParam, id IdParam)
	// ListVersions Version history of one manifest
	// (GET /manifests/{kind}/{id}/versions)
	ListVersions(w http.ResponseWriter, r *http.Request, kind KindParam, id IdParam)
	// GetVersion One historical version of a manifest
	// (GET /manifests/{kind}/{id}/versions/{n})
	GetVersion(w http.ResponseWriter, r *http.Request, kind KindParam, id IdParam, n int)
	// DiscardWorking Throw away a staged draft and go back to what the vault holds. The operation that could not exist before drafts were staged: the working copy used to be the file, so there was nothing to go back to. A ref the vault has never held leaves nothing behind, which is the honest answer rather than an empty manifest.
	// (DELETE /manifests/{kind}/{id}/working)
	DiscardWorking(w http.ResponseWriter, r *http.Request, kind KindParam, id IdParam)
	// GetWorking The working copy as last saved, decoded, so an interface or a conformance driver can read the draft back without a version.
	// (GET /manifests/{kind}/{id}/working)
	GetWorking(w http.ResponseWriter, r *http.Request, kind KindParam, id IdParam)
	// PutWorking Stage a draft. Writes to the vault's staging directory, not to the vault's own tree, and does not include the ref: autosave is not a decision to add something to the vault. A save promotes it.
	// (PUT /manifests/{kind}/{id}/working)
	PutWorking(w http.ResponseWriter, r *http.Request, kind KindParam, id IdParam)
	// GetPresenceDocument The document that carries presence for screens not about one manifest
	// (GET /presence)
	GetPresenceDocument(w http.ResponseWriter, r *http.Request)
	// GetSchema The JSON Schema document for a kind
	// (GET /schemas/{kind})
	GetSchema(w http.ResponseWriter, r *http.Request, kind KindParam)
	// GetSession Who this request acts as, as the engine records it
	// (GET /session)
	GetSession(w http.ResponseWriter, r *http.Request)
	// GetSettings The singleton configuration, defaulted where unset
	// (GET /settings)
	GetSettings(w http.ResponseWriter, r *http.Request)
	// ListSnapshots Every snapshot (version) across all kinds, newest first, with pagination
	// (GET /snapshots)
	ListSnapshots(w http.ResponseWriter, r *http.Request, params ListSnapshotsParams)
	// Sync The sync socket (automerge-repo network protocol, version 1)
	// (GET /sync)
	Sync(w http.ResponseWriter, r *http.Request)
	// ValidateManifest Validate a manifest without storing it
	// (POST /validate/{kind})
	ValidateManifest(w http.ResponseWriter, r *http.Request, kind KindParam)
	// GetVault The vault state manifest
	// (GET /vault)
	GetVault(w http.ResponseWriter, r *http.Request)
	// ApplyRef Include a manifest in the live state
	// (POST /vault/apply)
	ApplyRef(w http.ResponseWriter, r *http.Request)
	// ListExcluded Manifests that were excluded from the live state with reasons
	// (GET /vault/excluded)
	ListExcluded(w http.ResponseWriter, r *http.Request)
	// RecoverRef Re-include an excluded manifest in the live state
	// (POST /vault/recover)
	RecoverRef(w http.ResponseWriter, r *http.Request)
	// ListUnapplied Manifest files present but not included in the live state
	// (GET /vault/unapplied)
	ListUnapplied(w http.ResponseWriter, r *http.Request)
}

